CREATE INDEX IF NOT EXISTS call_logs_org_started_idx ON call_logs (organization_id, started_at);

CREATE INDEX IF NOT EXISTS call_logs_org_user_started_idx ON call_logs (organization_id, user_id, started_at);

CREATE INDEX IF NOT EXISTS leads_org_created_idx ON leads (organization_id, created_at);

CREATE INDEX IF NOT EXISTS leads_org_open_owner_idx ON leads (organization_id, assigned_to_id) WHERE stage_category = 'OPEN' AND merged_into_id IS NULL;

CREATE INDEX IF NOT EXISTS leads_org_won_at_idx ON leads (organization_id, won_at) WHERE stage_category = 'WON';

CREATE INDEX IF NOT EXISTS sales_records_org_lead_closed_idx ON sales_records (organization_id, lead_id, closed_at);

CREATE INDEX IF NOT EXISTS tasks_org_completed_idx ON tasks (organization_id, completed_at) WHERE status = 'DONE';

CREATE INDEX IF NOT EXISTS tasks_org_due_idx ON tasks (organization_id, due_at);

CREATE INDEX IF NOT EXISTS tasks_open_overdue_idx ON tasks (organization_id, assigned_to_id, due_at) WHERE status = 'OPEN';
